/*
  The statement provided is incomplete: it only gives a high-level description
  without the exact input format or the precise semantics of the "duplicated
  substrings" hints.

  To still provide a usable, runnable program, this solution supports the most
  natural interpretation of the described task:

  - We have a secret string of length n.
  - Some hints fix letters at certain positions.
  - Some hints say two substrings are equal, i.e.
        s[a + i] == s[b + i] for i = 0..len-1
    which induces equality constraints between positions.
  - For queried positions, if the letter can be deduced uniquely from fixed
    letters propagated through these equalities, output it; otherwise output '?'.

  Assumed input format:
    n f d q
    f lines: pos ch
    d lines: a b len
    q integers (possibly across multiple lines): queried positions

  Positions are 1-based.

  If the actual judge format differs, adapt parsing accordingly.
*/

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, f, d, q;
    if (!(cin >> n >> f >> d >> q)) return 0;

    DSU dsu(n);

    vector<pair<int,char>> fixedHints;
    fixedHints.reserve(f);

    for (int i = 0; i < f; ++i) {
        int pos;
        char ch;
        cin >> pos >> ch;
        fixedHints.push_back({pos, ch});
    }

    for (int i = 0; i < d; ++i) {
        int a, b, len;
        cin >> a >> b >> len;
        for (int j = 0; j < len; ++j) {
            if (a + j >= 1 && a + j <= n && b + j >= 1 && b + j <= n)
                dsu.unite(a + j, b + j);
        }
    }

    vector<char> compChar(n + 1, 0);
    vector<bool> bad(n + 1, false);

    for (auto [pos, ch] : fixedHints) {
        if (pos < 1 || pos > n) continue;
        int r = dsu.find(pos);
        if (compChar[r] == 0) compChar[r] = ch;
        else if (compChar[r] != ch) bad[r] = true; // contradictory hints => unknown
    }

    string ans;
    ans.reserve(q);
    for (int i = 0; i < q; ++i) {
        int pos;
        cin >> pos;
        char out = '?';
        if (1 <= pos && pos <= n) {
            int r = dsu.find(pos);
            if (!bad[r] && compChar[r] != 0) out = compChar[r];
        }
        ans.push_back(out);
    }

    cout << ans << '\n';
    return 0;
}

