#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int a, b, len;
} Dup;

typedef struct {
    int *p;
    unsigned char *r;
    int n;
} DSU;

static void dsu_init(DSU *d, int n) {
    d->n = n;
    d->p = (int*)malloc((n + 1) * sizeof(int));
    d->r = (unsigned char*)calloc(n + 1, sizeof(unsigned char));
    for (int i = 1; i <= n; i++) d->p[i] = i;
}

static int dsu_find(DSU *d, int x) {
    if (d->p[x] != x) d->p[x] = dsu_find(d, d->p[x]);
    return d->p[x];
}

static void dsu_union(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return;
    if (d->r[a] < d->r[b]) {
        d->p[a] = b;
    } else if (d->r[a] > d->r[b]) {
        d->p[b] = a;
    } else {
        d->p[b] = a;
        d->r[a]++;
    }
}

static int cmp_dup(const void *A, const void *B) {
    const Dup *x = (const Dup*)A;
    const Dup *y = (const Dup*)B;
    if (x->len != y->len) return y->len - x->len; /* descending by len */
    if (x->a != y->a) return x->a - y->a;
    return x->b - y->b;
}

int main(void) {
    int n, mFixed, mDup, q;
    if (scanf("%d %d %d %d", &n, &mFixed, &mDup, &q) != 4) return 0;

    DSU dsu;
    dsu_init(&dsu, n);

    char *fixed = (char*)malloc((n + 1) * sizeof(char));
    for (int i = 1; i <= n; i++) fixed[i] = 0;

    for (int i = 0; i < mFixed; i++) {
        int pos;
        char s[8];
        scanf("%d %7s", &pos, s);
        fixed[pos] = s[0];
    }

    Dup *dups = (Dup*)malloc((mDup > 0 ? mDup : 1) * sizeof(Dup));
    for (int i = 0; i < mDup; i++) {
        scanf("%d %d %d", &dups[i].a, &dups[i].b, &dups[i].len);
    }

    /* Merge equal substrings efficiently:
       Process intervals by decreasing length. For a rule (a,b,len),
       union a with b, a+1 with b+1, ..., a+len-1 with b+len-1.
       To avoid O(total length), use a "next unprocessed position" trick. */
    qsort(dups, mDup, sizeof(Dup), cmp_dup);

    int *nxt = (int*)malloc((n + 2) * sizeof(int));
    for (int i = 1; i <= n + 1; i++) nxt[i] = i;

    /* find-next structure over offsets inside currently processed interval */
    int find_next(int x) {
        int y = x;
        while (nxt[y] != y) y = nxt[y];
        while (nxt[x] != x) {
            int t = nxt[x];
            nxt[x] = y;
            x = t;
        }
        return y;
    }

    for (int i = 0; i < mDup; i++) {
        int a = dups[i].a, b = dups[i].b, len = dups[i].len;
        int end = len;
        int k = 1;
        while ((k = find_next(k)) <= end) {
            dsu_union(&dsu, a + k - 1, b + k - 1);
            nxt[k] = k + 1;
        }
        /* reset touched nxt positions for next constraint */
        for (int t = 1; t <= len; t++) nxt[t] = t;
    }

    char *repChar = (char*)malloc((n + 1) * sizeof(char));
    for (int i = 1; i <= n; i++) repChar[i] = 0;

    for (int i = 1; i <= n; i++) {
        if (fixed[i]) {
            int r = dsu_find(&dsu, i);
            if (!repChar[r]) repChar[r] = fixed[i];
        }
    }

    for (int i = 0; i < q; i++) {
        int pos;
        scanf("%d", &pos);
        int r = dsu_find(&dsu, pos);
        putchar(repChar[r] ? repChar[r] : '?');
    }
    putchar('\n');

    free(dsu.p);
    free(dsu.r);
    free(fixed);
    free(dups);
    free(nxt);
    free(repChar);
    return 0;
}

