/*
We model the unknown string positions as variables.
Hints are of two types:
1) Fixed letter at a position.
2) Two substrings are equal, which means corresponding positions are equal.

Thus we can use DSU (Union-Find) over positions 1..n.
- Merge positions implied equal by duplicate-substring hints.
- If any position in a component has a fixed letter, then the whole component has that letter.
  If conflicting letters appear in one component, the statement would be inconsistent; the
  problem statement typically guarantees valid input, but we handle it by marking unknown.

For each queried position, output:
- the known letter of its component, or
- '?' if not deducible.

Input format assumed from statement:
n m k q
then m lines: position letter
then k lines: a b len   meaning s[a..a+len-1] = s[b..b+len-1]
then q integers: queried positions

Because the original statement shown here is abbreviated, this is the most natural interpretation.
To support both space/newline separated query positions, we just read q integers with FastScanner.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class DSU {
        int[] p, r;

        DSU(int n) {
            p = new int[n + 1];
            r = new int[n + 1];
            for (int i = 1; i <= n; i++) p[i] = i;
        }

        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }

        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) {
                p[a] = b;
            } else if (r[a] > r[b]) {
                p[b] = a;
            } else {
                p[b] = a;
                r[a]++;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        int m = fs.nextInt();
        int k = fs.nextInt();
        int q = fs.nextInt();

        DSU dsu = new DSU(n);

        int[] fixedPos = new int[m];
        char[] fixedChar = new char[m];

        for (int i = 0; i < m; i++) {
            fixedPos[i] = fs.nextInt();
            fixedChar[i] = fs.next().charAt(0);
        }

        for (int i = 0; i < k; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int len = fs.nextInt();
            for (int j = 0; j < len; j++) {
                dsu.union(a + j, b + j);
            }
        }

        char[] compChar = new char[n + 1];
        boolean[] bad = new boolean[n + 1];

        for (int i = 0; i < m; i++) {
            int root = dsu.find(fixedPos[i]);
            char c = fixedChar[i];
            if (compChar[root] == 0) compChar[root] = c;
            else if (compChar[root] != c) bad[root] = true;
        }

        StringBuilder ans = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int pos = fs.nextInt();
            int root = dsu.find(pos);
            char out = (bad[root] || compChar[root] == 0) ? '?' : compChar[root];
            ans.append(out);
        }

        System.out.print(ans.toString());
    }
}

import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)

    # Assumed input format:
    # n m k
    # then m hints:
    #   either: 1 pos ch        -> fixed letter at position pos
    #   or:     2 a b length    -> s[a:a+length) == s[b:b+length)
    # then k queried positions
    #
    # Output letters for queried positions in one line, using '?' if unknown.
    #
    # Positions are treated as 1-based.

    try:
        n = int(next(it))
        m = int(next(it))
        k = int(next(it))
    except StopIteration:
        return

    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    fixed = []

    for _ in range(m):
        t = int(next(it))
        if t == 1:
            pos = int(next(it))
            ch = next(it)
            fixed.append((pos, ch))
        else:
            a = int(next(it))
            b = int(next(it))
            length = int(next(it))
            # Naive union of duplicated substring positions
            for d in range(length):
                if 1 <= a + d <= n and 1 <= b + d <= n:
                    union(a + d, b + d)

    comp_char = {}
    conflict = set()

    for pos, ch in fixed:
        if not (1 <= pos <= n):
            continue
        r = find(pos)
        if r in comp_char:
            if comp_char[r] != ch:
                conflict.add(r)
        else:
            comp_char[r] = ch

    ans = []
    for _ in range(k):
        pos = int(next(it))
        if not (1 <= pos <= n):
            ans.append('?')
            continue
        r = find(pos)
        if r in conflict:
            ans.append('?')
        else:
            ans.append(comp_char.get(r, '?'))

    sys.stdout.write(''.join(ans))

if __name__ == "__main__":
    main()
